50
</input>
<input>
3 100
50 50 100
</input>
<input>
2 50
50 50
</input>
</sample_inputs>

Here is the source code:
<source_code>
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class C {
	static int n, k, f, h;
	static int[][] dp1;
	static long[][][] dp2;
	static long[][] c;
	static int mod = 1000000007;
	static int r1;

	public static void main(String[] args) throws IOException {
		InputReader in = new InputReader();
		n = in.nextInt();
		k = in.nextInt();
		f = 0;
		h = 0;
		for (int i = 0; i < n; i++) {
			int w = in.nextInt();
			if (w == 100)
				h++;
			else
				f++;
		}

		nCr(55, 55);
		dp1 = new int[55][55];
		for (int i = 0; i < 55; i++)
			Arrays.fill(dp1[i], -1);
		dp2 = new long[55][55][102];
		for (int i = 0; i < 55; i++)
			for (int j = 0; j < 55; j++)
				Arrays.fill(dp2[i][j], -1);

		r1 = getMin(f, h);
		if (r1 >= 1 << 25) {
			System.out.println(-1);
			System.out.println(0);
		} else {
			long r2 = go(f, h, 0);
			System.out.println(r1);
			System.out.println(r2);
		}
	}

	public static long go(int x, int y, int t) {
		if (x == 0 && y == 0 && t == r1)
			return 1;
		if (t >= r1)
			return 0;
		if (dp2[x][y][t] != -1)
			return dp2[x][y][t];

		long ret = 0;
		int side = t % 2;

		for (int i = 0; i <= x; i++) {
			for (int j = 0; j <= y; j++) {
				if (i + j == 0)
					continue;
				if (i * 50 + j * 100 > k)
					continue;
				if (side == 1 && i == x && j == y)
					continue;

				int newX = side == 0 ? x - i : x + i;
				int newY = side == 0 ? y - j : y + j;

				long ways = (c[x][i] * c[y][j]) % mod;
				ret = (ret + (go(newX, newY, t + 1) * ways) % mod) % mod;
			}
		}
		return dp2[x][y][t] = ret;
	}

	public static int getMin(int x, int y) {
		if (x == 0 && y == 0)
			return 0;
		if (dp1[x][y] != -1)
			return dp1[x][y];

		int ret = 1 << 25;

		for (int i = 0; i <= x; i++) {
			for (int j = 0; j <= y; j++) {
				if (i + j == 0)
					continue;
				if (i * 50 + j * 100 > k)
					continue;

				if (i == x && j == y) {
					ret = Math.min(ret, 1);
				} else {
					int minAfter;
					if (i == 0) {
						minAfter = getMin(x + 1, y - j);
					} else if (j == 0) {
						minAfter = getMin(x - i + 1, y);
					} else {
						minAfter = Math.min(getMin(x - i + 1, y - j), getMin(x - i, y - j + 1));
					}
					ret = Math.min(ret, 2 + minAfter);
				}
			}
		}
		return dp1[x][y] = ret;
	}

	public static void nCr(int n, int r) {
		c = new long[n + 1][r + 1];
		for (int i = 0; i <= n; i++) {
			c[i][0] = 1;
			for (int j = 1; j <= Math.min(i, r); j++) {
				c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % mod;
			}
		}
	}

	static class InputReader {
		BufferedReader in;
		StringTokenizer st;

		public InputReader() throws IOException {
			in = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreElements()) {
				st = new StringTokenizer(in.readLine());
			}
			return st.nextToken();
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}
	}
}
